// TypeScript interfaces for OOTDay Fashion Assistant

// Export all new type definitions
export * from './types/enums'
export * from './types/localization-types'
export * from './types/product-types'

// Re-export FlatLayItem from image-types for use in ChatMessage
import type { FlatLayItem } from './types/image-types'
export type { FlatLayItem }

// Legacy interfaces maintained for backward compatibility
// These will gradually be replaced by EnhancedProduct
export interface OutfitRequest {
  query: string
  userId?: string
  context?: {
    occasion?: string
    weather?: string
    preferences?: string[]
  }
}

export interface OutfitResponse {
  outfits: Outfit[]
  conversationId: string
  suggestions: string[]
}

export interface Outfit {
  id: string
  title: string
  description: string
  totalPrice: number
  items: Product[]
  imageUrl?: string
  /** Flat-lay image URL for outfit visualization (v5.0) */
  flatLayImageUrl?: string
  /** Flat-lay image as base64 fallback (v5.0) */
  flatLayImageBase64?: string
  /** Flag indicating flat-lay image is being generated (v5.0) */
  isGeneratingFlatLay?: boolean
  /** Try-on image URL for fitting model visualization (v6.0) */
  tryOnImageUrl?: string
  /** Try-on image as base64 fallback (v6.0) */
  tryOnImageBase64?: string
  /** Flag indicating try-on image is being generated (v6.0) */
  isGeneratingTryOn?: boolean
  /** Pinterest 2026 aesthetic category (v7.0) */
  aesthetic?: import('./types/enums').AestheticCategory
  /** Trending color palette (v7.0) */
  colorPalette?: import('./types/enums').ColorPalette
  /** Layering style (v7.0) */
  layeringStyle?: import('./types/enums').LayeringStyle
}

/**
 * @deprecated Use EnhancedProduct from './types/product-types' instead
 * This interface is kept for backward compatibility
 */
export interface Product {
  sku: string
  name: string
  brand: string
  price: number
  imageUrl: string
  availability: "in_stock" | "low_stock" | "out_of_stock"
  storeLocations?: string[]
  onlineUrl?: string
  sizes?: string[]
  colors?: string[]
  category?: string // "Men", "Women", or other categories
  subCategory?: string // "Blazer", "Skirt", "Pants", etc.
  visualDescription?: string // For AI Image Generation prompt
  occasion?: string[] // For filtering
}

export interface ChatMessage {
  id: string
  content: string
  sender: "user" | "assistant"
  timestamp: Date
  outfits?: Outfit[]
  /** Image URL for generated outfit visualization (v3.1) */
  imageUrl?: string
  /** Base64-encoded image data (v3.1) */
  imageBase64?: string
  /** Outfit description used for image generation (v3.1) */
  outfitDescription?: string
  /** Image display mode: 'portrait' (3:4) or 'flat-lay' (1:1 square) (v4.0) */
  displayMode?: 'portrait' | 'flat-lay'
  /** Recommended items for flat-lay display (v4.0) */
  recommendedItems?: FlatLayItem[]
}

export interface ConversationStarter {
  id: string
  text: string
  category: string
}

export interface FilterState {
  gender?: 'all' | 'men' | 'women'
  occasion?: string[]  // ['work', 'casual', 'date', 'formal']
  priceRange?: { min: number; max: number }
  searchQuery?: string
}

/**
 * Comprehensive Product Type Definitions
 * Enhanced product data model for AI Fashion Assistant
 */

import type {
  AvailabilityStatus,
  Gender,
  OccasionType,
  SeasonType,
  FormalityLevel,
  FitType,
  StyleTag,
  PatternType,
  BrandTier,
  OutfitRole,
  Currency,
  SizeStandard,
  ColorName,
  MaterialType,
  TagStructure,
} from './enums'
import type { LocalizedText } from './localization-types'

/**
 * Core Product Information
 */
export interface CoreProductInfo {
  // Unique identifier (FR-001)
  id: string
  sku: string

  // Product names - bilingual support (FR-002, FR-003)
  name: LocalizedText

  // Product description (FR-038)
  description?: LocalizedText

  // Brand information (FR-033, FR-034)
  brand: string
  brandTier?: BrandTier
}

/**
 * Pricing Information
 */
export interface PricingInfo {
  // Current price (FR-006)
  currentPrice: number

  // Original price for discounts (FR-007)
  originalPrice?: number

  // Currency (FR-008, FR-039)
  currency: Currency

  // Promotional information (FR-032)
  promotional?: string

  // Calculated discount percentage
  discountPercentage?: number
}

/**
 * Classification Information
 */
export interface ClassificationInfo {
  // Hierarchical category (FR-009, FR-010)
  category: {
    department?: string // Level 1
    category?: string // Level 2
    subcategory?: string // Level 3
    type?: string // Level 4
  }

  // Gender/demographic (FR-011)
  gender: Gender

  // Flexible tags (FR-012, FR-013)
  tags: {
    occasion?: OccasionType[]
    style?: StyleTag[]
    season?: SeasonType[]
    custom?: TagStructure[]
  }

  // Outfit role (FR-014, FR-047)
  role?: OutfitRole

  // Complete outfit flag (FR-045)
  isCompleteOutfit?: boolean
}

/**
 * Style & Aesthetic Attributes
 */
export interface StyleAttributes {
  // Color information (FR-015, FR-016)
  colors: {
    primary: ColorName | string
    secondary?: (ColorName | string)[]
  }

  // Pattern (FR-017)
  pattern?: PatternType

  // Formality level 1-10 (FR-018)
  formalityLevel: FormalityLevel

  // Style tags (FR-019)
  styleAttributes: StyleTag[]

  // Material/fabric (FR-020)
  material?: MaterialType | string

  // Season/weather (FR-021)
  seasonality: SeasonType[]
}

/**
 * Size & Fit Information
 */
export interface SizeInfo {
  // Available sizes (FR-025)
  availableSizes: string[]

  // Size standard (FR-026)
  sizeStandard?: SizeStandard

  // Fit description (FR-027)
  fit?: FitType

  // Detailed measurements (FR-028)
  measurements?: {
    [size: string]: {
      chest?: number
      waist?: number
      hips?: number
      length?: number
      shoulders?: number
      unit: 'cm' | 'in'
    }
  }
}

/**
 * Availability Information
 */
export interface AvailabilityInfo {
  // Availability status (FR-029)
  status: AvailabilityStatus

  // Stock quantity (FR-030)
  stockQuantity?: number

  // Store locations (FR-043)
  storeLocations?: string[]

  // Last updated timestamp
  lastUpdated?: Date
}

/**
 * Thai Market Specific Information
 */
export interface ThaiMarketInfo {
  // Cultural appropriateness (FR-036)
  culturalAppropriate: boolean

  // Special flags (FR-037)
  specialFlags?: {
    templeAppropriate?: boolean
    conservativeWorkplaceSuitable?: boolean
    thaiWeddingSuitable?: boolean
  }

  // Thai sizing information
  thaiSizeEquivalent?: string

  // Thai fashion sensibilities metadata
  thaiStyleNotes?: string
}

/**
 * Central Group Integration
 */
export interface CentralIntegration {
  // Central's SKU (FR-040, FR-044)
  centralSKU: string

  // Product URL (FR-031, FR-041)
  productUrl: string

  // Image URLs (FR-004, FR-005, FR-042)
  images: {
    primary: string
    additional?: string[]
  }

  // Central-specific metadata
  centralMetadata?: {
    categoryPath?: string
    productCode?: string
  }
}

/**
 * Outfit Composition Support
 */
export interface OutfitComposition {
  // Recommended pairings (FR-046)
  recommendedPairings?: string[] // Array of product IDs

  // Goes well with suggestions
  goesWellWith?: {
    tops?: string[]
    bottoms?: string[]
    footwear?: string[]
    accessories?: string[]
  }

  // Styling tips (FR-057)
  stylingTips?: LocalizedText
}

/**
 * Extensibility & Future Features
 */
export interface ExtensibilityFields {
  // User interaction tracking (FR-055)
  userInteractions?: {
    views?: number
    clicks?: number
    favorites?: number
    addedToOutfit?: number
  }

  // Reviews and ratings (FR-056)
  reviews?: {
    averageRating?: number
    totalReviews?: number
  }

  // Sustainability attributes (FR-058)
  sustainability?: {
    ecoFriendly?: boolean
    sustainableMaterial?: boolean
    ethicalProduction?: boolean
    certifications?: string[]
  }

  // Virtual try-on metadata (FR-059)
  virtualTryOn?: {
    available?: boolean
    modelUrl?: string
    arCompatible?: boolean
  }

  // Care instructions (FR-035)
  careInstructions?: LocalizedText
}

/**
 * Enhanced Product - Complete Interface
 * Combines all attribute groups into comprehensive product model
 */
export interface EnhancedProduct {
  // Core information
  id: string
  sku: string
  name: LocalizedText
  description?: LocalizedText
  brand: string
  brandTier?: BrandTier

  // Pricing
  pricing: PricingInfo

  // Classification
  classification: ClassificationInfo

  // Style attributes
  style: StyleAttributes

  // Size and fit
  sizing: SizeInfo

  // Availability
  availability: AvailabilityInfo

  // Thai market specific
  thaiMarket: ThaiMarketInfo

  // Central integration
  centralIntegration: CentralIntegration

  // Outfit composition
  outfit?: OutfitComposition

  // Extensibility
  extended?: ExtensibilityFields

  // Metadata
  metadata?: {
    createdAt?: Date
    updatedAt?: Date
    version?: string
  }
}

/**
 * Simplified Product Summary for AI Context
 * Token-efficient format for AI prompts
 */
export interface ProductSummary {
  id: string
  name: string
  brand: string
  price: number
  url: string // Product URL for recommendations
  category: string
  gender: Gender
  occasions: OccasionType[]
  formality: FormalityLevel
  colors: string[]
  style: StyleTag[]
  season: SeasonType[]
  role?: OutfitRole
}

/**
 * Product Filter Criteria
 */
export interface ProductFilterCriteria {
  gender?: Gender | Gender[]
  occasions?: OccasionType | OccasionType[]
  priceRange?: { min: number; max: number }
  formality?: { min: FormalityLevel; max: FormalityLevel }
  colors?: ColorName[]
  styles?: StyleTag[]
  seasons?: SeasonType[]
  brands?: string[]
  availability?: AvailabilityStatus[]
  roles?: OutfitRole[]
}

/**
 * Product Sort Options
 */
export type ProductSortField =
  | 'price-asc'
  | 'price-desc'
  | 'formality-asc'
  | 'formality-desc'
  | 'popularity'
  | 'newest'
  | 'relevance'

/**
 * Product Query Result
 */
export interface ProductQueryResult {
  products: EnhancedProduct[]
  total: number
  page?: number
  pageSize?: number
  filters?: ProductFilterCriteria
  sort?: ProductSortField
}
